import fr.hypercruise.LocalEngine;import org.json.*;import java.io.*;
public class SessionRunner082 {public static void main(String[] a)throws Exception {LocalEngine e=new LocalEngine(new android.content.Context(new File(a[0]),new File(a[1])));BufferedReader in=new BufferedReader(new InputStreamReader(System.in));String line;while((line=in.readLine())!=null){try{JSONObject p=new JSONObject(line),v;p=p.getJSONObject("payload");String kind=new JSONObject(line).getString("kind");if(kind.equals("localBegin"))v=e.begin(p);else if(kind.equals("localEnd"))v=e.end(p);else v=e.job(p);System.out.println(v.toString());}catch(Throwable t){System.out.println(new JSONObject().put("fatal",t.toString()).toString());}System.out.flush();}}}